@@ -0,0 +1,121 @@
+//! Database operations for the shared fencer-licence collection.
+//!
+//! These functions operate over a `cosmos::Collection<FencerLicenceFields>`
+//! supplied by the caller (`blob` wires it into `DbClient`). Passing the
+//! collection in keeps this crate free of any dependency on `blob`.
+
+use std::collections::HashMap;
+
+use chrono::{DateTime, Utc};
+use cosmos::{Collection, Select, SelectBuilder, SqlFilter, id_in};
+use ids::{FencerId, Identified, TypedId, UserId};
+
+use crate::model::FencerLicenceFields;
+
+/// Stable storage key for one fencer's shared licence. Distinct from the
+/// fencers-collection document id, so a fencer refresh that patches
+/// `FencerFields` cannot address this record.
+pub fn document_id(fencer_id: &TypedId<FencerId>) -> String {
+  format!("bfl-{}", fencer_id)
+}
+
+/// Loads the shared licence document for `fencer_id`, if one has ever been
+/// written (including an explicit clear).
+pub async fn get(
+  licences: &Collection<FencerLicenceFields>,
+  fencer_id: &TypedId<FencerId>,
+) -> anyhow::Result<Option<Identified<FencerLicenceFields>>> {
+  licences.get_document(&document_id(fencer_id)).await
+}
+
+/// The current membership id, or `None` if unset, cleared, or never written.
+pub async fn get_membership_id(
+  licences: &Collection<FencerLicenceFields>,
+  fencer_id: &TypedId<FencerId>,
+) -> anyhow::Result<Option<String>> {
+  Ok(
+    get(licences, fencer_id)
+      .await?
+      .and_then(|doc| doc.fields.membership_id),
+  )
+}
+
+struct ByFencerIdsFilter {
+  document_ids: Vec<String>,
+}
+
+impl SqlFilter for ByFencerIdsFilter {
+  fn to_select(&self) -> anyhow::Result<Select> {
+    Ok(
+      SelectBuilder::all()
+        .condition(id_in(&self.document_ids)?)
+        .build()?,
+    )
+  }
+}
+
+/// Loads the current membership id for every fencer in `fencer_ids` in a
+/// single query, keyed by fencer id. A fencer with no shared record (never
+/// written) is simply absent from the map rather than mapped to `None`.
+pub async fn get_membership_ids(
+  licences: &Collection<FencerLicenceFields>,
+  fencer_ids: &[TypedId<FencerId>],
+) -> anyhow::Result<HashMap<TypedId<FencerId>, Option<String>>> {
+  if fencer_ids.is_empty() {
+    return Ok(HashMap::new());
+  }
+  let document_ids = fencer_ids.iter().map(document_id).collect();
+  let docs = licences
+    .list_documents_filtered(ByFencerIdsFilter { document_ids })
+    .await?;
+  Ok(
+    docs
+      .into_iter()
+      .map(|doc| (doc.fields.fencer_id, doc.fields.membership_id))
+      .collect(),
+  )
+}
+
+/// Last-write-wins upsert. `membership_id: None` is an explicit clear; the
+/// document is kept so `set_by` / `set_at` remain.
+pub async fn upsert(
+  licences: &Collection<FencerLicenceFields>,
+  fencer_id: TypedId<FencerId>,
+  membership_id: Option<String>,
+  set_by: TypedId<UserId>,
+  set_at: DateTime<Utc>,
+) -> anyhow::Result<Identified<FencerLicenceFields>> {
+  let doc = Identified {
+    id: document_id(&fencer_id),
+    fields: FencerLicenceFields::new(fencer_id, membership_id, set_by, set_at),
+    partition: Some("flunge".to_string()),
+  };
+  licences.upsert_document(doc).await
+}
+
+/// Every licence document. Used by standings-history capture and by
+/// migration to skip fencers that already have a shared record.
+pub async fn list_all(
+  licences: &Collection<FencerLicenceFields>,
+) -> anyhow::Result<Vec<Identified<FencerLicenceFields>>> {
+  licences.list_documents().await
+}
+
+#[cfg(test)]
+mod tests {
+  use super::*;
+
+  #[test]
+  fn document_id_is_not_the_fencer_view_id() {
+    let fencer_id = TypedId::<FencerId>::usaf("100344622");
+    let id = document_id(&fencer_id);
+    assert_eq!(id, "bfl-f.u.100344622");
+    assert_ne!(id, fencer_id.to_string());
+  }
+
+  #[test]
+  fn document_id_is_stable_for_a_given_fencer() {
+    let fencer_id = TypedId::<FencerId>::usaf("100344622");
+    assert_eq!(document_id(&fencer_id), document_id(&fencer_id));
+  }
+}

