//! v3 REST API for user-owned writes that need their own validation rather
//! than the generic `PATCH /api/v2/user/me` json-patch path — currently just
//! the British Fencing membership id. The caller must track the fencer; the
//! value is written to the shared fencer-licence record, last write wins.
//! See `docs/design-docs/british-fencing-rankings-as-a-standings-source.md`,
//! "Where the membership id lives", for why this route exists instead of a
//! json-patch op on `/trackedFencers`.

pub mod rest {
  use std::str::FromStr;

  use axum::extract::Path;
  use axum::http::StatusCode;
  use axum::{Extension, Json};
  use ids::{FencerId, TypedId};
  use routez::RoutezRouter;
  use serde::Deserialize;
  use thiserror::Error;

  use crate::auth::AuthenticatedUser;
  use crate::share::is_connected_fencer;
  use crate::v2::user::set_tracked_fencer_british_fencing_licence;

  /// Mirrors the design doc: "rejects anything that is not 1-32 characters".
  const MAX_MEMBERSHIP_ID_LEN: usize = 32;

  #[derive(Debug, Error)]
  pub enum UserApiError {
    #[error("Fencer is not a connected fencer for this user")]
    FencerNotTracked,
    #[error("Invalid fencer id")]
    InvalidFencerId,
    #[error("British Fencing membership id must be 1-32 characters")]
    InvalidMembershipId,
    #[error(transparent)]
    Database(#[from] anyhow::Error),
  }

  routez::error_into_response! {
    UserApiError, err,
    log = "User API error",
    UserApiError::FencerNotTracked => StatusCode::NOT_FOUND, err.to_string();
    UserApiError::InvalidFencerId => StatusCode::BAD_REQUEST, err.to_string();
    UserApiError::InvalidMembershipId => StatusCode::BAD_REQUEST, err.to_string();
    UserApiError::Database(_) => StatusCode::INTERNAL_SERVER_ERROR, "Internal server error";
  }

  type Result<T> = std::result::Result<T, UserApiError>;

  /// Router mounted at `/user` in the protected v3 router.
  pub fn router() -> RoutezRouter {
    RoutezRouter::new().route_put(
      "/tracked-fencers/{fencer_id}/british-fencing-membership",
      set_british_fencing_membership,
    )
  }

  #[derive(Debug, Deserialize)]
  #[serde(rename_all = "camelCase")]
  struct SetBritishFencingMembershipRequest {
    #[serde(default)]
    membership_id: Option<String>,
  }

  /// Normalizes a raw `membershipId` request value: `None`, an empty string,
  /// or a whitespace-only string all clear the licence (`Ok(None)`);
  /// otherwise the trimmed value is returned if it is 1-32 characters (by
  /// `chars().count()`, not byte length), and rejected above that.
  fn normalize_membership_id(raw: Option<String>) -> Result<Option<String>> {
    let Some(raw) = raw else {
      return Ok(None);
    };
    let trimmed = raw.trim();
    if trimmed.is_empty() {
      Ok(None)
    } else if trimmed.chars().count() > MAX_MEMBERSHIP_ID_LEN {
      Err(UserApiError::InvalidMembershipId)
    } else {
      Ok(Some(trimmed.to_string()))
    }
  }

  /// Sets or clears the shared British Fencing membership id for a fencer
  /// the caller tracks. Last write wins; every other tracker sees the new
  /// value. `membershipId: null` (or an empty / whitespace-only string)
  /// clears it; otherwise the trimmed value must be 1-32 characters.
  async fn set_british_fencing_membership(
    Extension(auth): Extension<AuthenticatedUser>,
    Path(fencer_id): Path<String>,
    Json(request): Json<SetBritishFencingMembershipRequest>,
  ) -> Result<StatusCode> {
    let fencer_id =
      TypedId::<FencerId>::from_str(&fencer_id).map_err(|_| UserApiError::InvalidFencerId)?;

    if !is_connected_fencer(&auth.user.fields.tracked_fencers, &fencer_id) {
      return Err(UserApiError::FencerNotTracked);
    }

    let licence = normalize_membership_id(request.membership_id)?;

    let fencer_id_str = fencer_id.to_view_string();
    let tracked =
      set_tracked_fencer_british_fencing_licence(&auth.user.id, &fencer_id_str, licence).await?;
    if !tracked {
      return Err(UserApiError::FencerNotTracked);
    }

    Ok(StatusCode::NO_CONTENT)
  }

  #[cfg(test)]
  mod tests {
    use axum::response::IntoResponse;

    use super::*;

    #[test]
    fn fencer_not_tracked_is_not_found() {
      let response = UserApiError::FencerNotTracked.into_response();
      assert_eq!(response.status(), StatusCode::NOT_FOUND);
    }

    #[test]
    fn invalid_fencer_id_is_bad_request() {
      let response = UserApiError::InvalidFencerId.into_response();
      assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn invalid_membership_id_is_bad_request() {
      let response = UserApiError::InvalidMembershipId.into_response();
      assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn database_error_is_internal_server_error() {
      let response = UserApiError::Database(anyhow::anyhow!("boom")).into_response();
      assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
    }

    #[test]
    fn normalize_none_clears() {
      assert_eq!(normalize_membership_id(None).unwrap(), None);
    }

    #[test]
    fn normalize_whitespace_only_clears() {
      assert_eq!(
        normalize_membership_id(Some("   ".to_string())).unwrap(),
        None
      );
    }

    #[test]
    fn normalize_trims() {
      assert_eq!(
        normalize_membership_id(Some(" 142013 ".to_string())).unwrap(),
        Some("142013".to_string())
      );
    }

    #[test]
    fn normalize_accepts_exactly_max_length() {
      let value = "a".repeat(MAX_MEMBERSHIP_ID_LEN);
      assert_eq!(
        normalize_membership_id(Some(value.clone())).unwrap(),
        Some(value)
      );
    }

    #[test]
    fn normalize_rejects_over_max_length() {
      let value = "a".repeat(MAX_MEMBERSHIP_ID_LEN + 1);
      assert!(matches!(
        normalize_membership_id(Some(value)),
        Err(UserApiError::InvalidMembershipId)
      ));
    }

    #[test]
    fn normalize_rejects_over_max_length_multibyte_chars() {
      // 33 multi-byte characters: over the 32-char limit by `chars().count()`
      // even though the check must not use byte length (each char is >1 byte).
      let value = "é".repeat(MAX_MEMBERSHIP_ID_LEN + 1);
      assert!(matches!(
        normalize_membership_id(Some(value)),
        Err(UserApiError::InvalidMembershipId)
      ));
    }
  }
}
