/// Per-container options a caller can request when wiring a collection, applied (where the
/// underlying SDK allows) when [`CosmosClient::ensure_collections_exist`] creates a missing
/// container. Defaults to every field unset, i.e. the account's standard container.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct CollectionOptions {
  /// Cosmos container-level default TTL, in seconds. `-1` enables TTL with no default expiry
  /// (every document's own `ttl` field governs its expiry); a positive value is the default
  /// expiry for a document with no `ttl` field of its own. `None` leaves TTL disabled, the
  /// account's existing convention.
  ///
  /// **Known gap:** `azure_data_cosmos` 0.20.0's `create_collection` request body has no
  /// `defaultTtl` field, so this crate cannot actually set it when creating a container - see
  /// the warning [`CosmosClient::ensure_collections_exist`] logs on every boot for a container
  /// requesting one, whether or not this process created it. Until the SDK is upgraded (or
  /// the container is provisioned out of band, e.g. via `az cosmosdb sql container update
  /// --ttl`), a document's own `ttl` field is inert. Recorded here anyway so the option is
  /// real and forward-compatible: a future SDK upgrade only has to fill in the request body,
  /// not re-plumb every call site.
  pub default_ttl: Option<i32>,
}

pub struct CosmosClient {
  client: DatabaseClient,
  dry: bool,
  /// Name and requested options of every container handed out via [`CosmosClient::collection`]
  /// or [`CosmosClient::collection_with_options`] so far. Recorded at the point handles are
  /// created (not maintained as a second, hand-written list) so that wiring a new collection
  /// automatically makes it a provisioning requirement - there is no separate list to remember to
  /// update.
  handed_out: std::sync::Mutex<Vec<(String, CollectionOptions)>>,
}

impl CosmosClient {
  pub fn connect(account: &str, primary_key: &str, db: &str, dry: bool) -> Result<Self> {
    let client = azure_data_cosmos::clients::CosmosClient::new(
      account,
      AuthorizationToken::primary_key(primary_key)?,
    );
    let database_client = client.database_client(db.to_string());
    info!("Connected to cosmosdb");
    if dry {
      info!("IN DRY RUN MODE - NOTHING WILL BE WRITTEN TO COSMOS");
    }
    Ok(Self {
      client: database_client,
      dry,
      handed_out: std::sync::Mutex::new(Vec::new()),
    })
  }

  pub fn collection<
    T: Serialize + DeserializeOwned + Send + Sync + Clone + 'static + Eq + Hash + Debug + HasIdDetail,
  >(
    &self,
    name: &str,
    Ok(new.clone())
  }

  pub async fn create_document(&self, doc: T) -> Result<Identified<T>> {
    let mut docs = self.create_documents(vec![doc]).await?;
    Ok(docs.remove(0))
  }

  pub async fn create_documents(&self, docs: Vec<T>) -> Result<Vec<Identified<T>>> {
    let id_docs = docs
      .into_iter()
      .map(Identified::generate_partitioned_id)
      .collect::<Vec<_>>();
    // create an id for every document.
    for identified in id_docs.clone().into_iter() {
      debug!(
        collection = %self.name,
        document = ?identified,
        "Creating document"
      );
      if !self.dry {
        self
          .collection_client
          .create_document(identified)
          .is_upsert(true)
          .await?;
      } else {
        warn!(collection = %self.name, "Skipping create due to dry run flag");
      }
    }
    Ok(id_docs)
  }

  pub async fn upsert_document(&self, doc: Identified<T>) -> Result<Identified<T>> {
    debug!(collection = %self.name, document = ?doc, "Upserting document");
    if !self.dry {
      self
        .collection_client
        .create_document(doc.clone())
        .is_upsert(true)
        .await?;
    } else {
      warn!(collection = %self.name, "Skipping upsert due to dry run flag");
    }
    Ok(doc)
  }

