/// Gets all unique connected fencer USAF IDs across all users.
/// Returns a set of USAF IDs (extracted from view format `f.u.xxx`).
/// Fencers with non-USAF IDs (e.g., database IDs) are skipped.
pub async fn get_all_connected_fencer_ids() -> Result<std::collections::HashSet<u32>> {
  let users = get_all_users().await?;
  let mut fencer_ids = std::collections::HashSet::new();

  for user in users {
    for tracked in user.fields.tracked_fencers {
      if let Some(usaf_id) = tracked.fencer_id.usaf_id() {
        fencer_ids.insert(usaf_id);
      }
    }
  }

  Ok(fencer_ids)
}

/// Connected fencer USAF ids plus each fencer's shared British Fencing
/// licence, when one is set. One licence per fencer: the value is a
/// property of the fencer, not a per-account assertion, so this cannot
/// return two licences for the same id.
pub async fn get_all_connected_fencer_ids_and_licences()
-> Result<(std::collections::HashSet<u32>, Vec<(u32, String)>)> {
  let fencer_ids = get_all_connected_fencer_ids().await?;
  let licences = crate::fencer_licence::repository::list_all(&DB.fencer_british_licences).await?;
  let mut pairs = Vec::new();
  for doc in licences {
    let Some(usaf_id) = doc.fields.fencer_id.usaf_id() else {
      continue;
    };
    if !fencer_ids.contains(&usaf_id) {
      continue;
    }
    let Some(membership_id) = doc.fields.membership_id else {
      continue;
    };
    pairs.push((usaf_id, membership_id));
  }
  Ok((fencer_ids, pairs))
}

/// Gets one user's own connected fencer USAF IDs (the fencers this account
/// tracks). Unlike [`get_all_connected_fencer_ids`], which unions every user
/// in the database and exists solely for admin/background jobs that
/// intentionally operate over the whole population, this is the
/// account-scoped lookup for user-facing (authenticated) request handlers.
pub fn get_connected_fencer_ids_for_user(user: &User) -> std::collections::HashSet<u32> {
  user
    .fields
    .tracked_fencers
    .iter()
    .filter_map(|tracked| tracked.fencer_id.usaf_id())
    .collect()
}

pub async fn get_fencer_standings(
  fencer_id: TypedId<FencerId>,
  british_licence: Option<&str>,
) -> Result<FencerStandingsResponse> {
  let usaf_id = resolve_standings_usaf_id(&fencer_id).await?;

  let raw_rankings = if let Some(usaf_id) = usaf_id {
    standings_index::lookup_standings(usaf_id)
      .await
      .map_err(|e| StandingsError::StandingsIndex(e.to_string()))?
  } else {
    Vec::new()
  };
  let rankings = collapse_regional_shared_entries(raw_rankings);
  let unified_is_new = if rankings
    .iter()
    .any(|ranking| ranking.scope == StandingScope::Unified)
  {
    Some(unified_new_marker_enabled().await?)
  } else {
    None
  };

  let mut items: Vec<FencerStandingItem> = Vec::with_capacity(rankings.len());
  for ranking in &rankings {
    let enrichment = if let Some(uid) = usaf_id {
      enrich_ranking(ranking, uid).await
    } else {
      StandingEnrichment::default()
    };
    if let Some(item) = fencer_standing_item(ranking, enrichment, unified_is_new) {
      items.push(item);
    }
  }

  if let Some(licence) = british_licence {
    items.extend(british_standing_items(licence).await);
  }

  sort_standings(&mut items);

  Ok(fencer_standings_response(fencer_id, usaf_id, items))
}

/// Shapes the response after USA Fencing and British items have been
/// assembled. `identity_resolved` deliberately reports USA Fencing identity
/// resolution only; British licence-matched items remain usable without one.
fn fencer_standings_response(
  fencer_id: TypedId<FencerId>,
  usaf_id: Option<u32>,
  standings: Vec<FencerStandingItem>,
) -> FencerStandingsResponse {
  FencerStandingsResponse {
    fencer_id,
    identity_resolved: usaf_id.is_some(),
    standings,
  }
}

/// Assembles this licence's British Fencing standing items, one per
/// configured table it appears on, gated on [`british_rankings_enabled`].
/// Ingestion runs regardless of the flag; this is the only place a British
/// item is ever kept from the response. A read failure (a bad Redis
/// connection, a corrupted payload) degrades to no British items rather than
/// failing the whole standings response, matching every other secondary
/// enrichment source in this file (see [`enrich_ranking`]'s own
/// cache-miss-is-not-an-error handling).
async fn british_standing_items(licence: &str) -> Vec<FencerStandingItem> {
  match british_rankings_enabled().await {
    Ok(true) => {}
    Ok(false) => return Vec::new(),
    Err(error) => {
      warn!(
        licence,
        ?error,
        "Failed to read British rankings runtime flag; omitting British standings"
      );
      return Vec::new();
    }
  }

  let mut conn = british_redis_connection().await;
  let entries = match british_fencing::store::read_licence_index_entries(&mut conn, licence).await {
    Ok(entries) => entries,
    Err(error) => {
      warn!(
        licence,
        ?error,
        "Failed to read British rankings licence index"
      );
      return Vec::new();
    }
  };

  let mut items = Vec::with_capacity(entries.len());
  for entry in &entries {
    match british_standing_item(&mut conn, entry).await {
      Ok(Some(item)) => items.push(item),
      // Not-yet-ranked: the entry's own table has since dropped this row (or
      // the table was never published). No item for that table, no error,
      // no placeholder -- see the design doc's "Not-yet-ranked".
      Ok(None) => {}
      Err(error) => {
        warn!(
          licence,
          table_id = %entry.table_id,
          ?error,
          "Failed to read a British rankings table"
        );
      }
    }
  }
  items
}

async fn british_redis_connection() -> redis::aio::MultiplexedConnection {
  RedisCache::get()
    .await
    .get_connection()
    .expect("RedisCache should provide a Redis connection")
}

/// Resolves one licence-index entry into a standing item, tolerating the
/// entry's `row_index` having drifted out from under it: `row_index` is
/// re-derived on every refresh (see
/// [`british_fencing::store::LicenceIndexEntry`]'s doc), so a reader that
/// trusted it blindly could return a different fencer's row if a refresh
/// landed between the licence-index read and this one. Falls back to a scan
/// when the pointer no longer lines up.
async fn british_standing_item(
  conn: &mut redis::aio::MultiplexedConnection,
  entry: &british_fencing::store::LicenceIndexEntry,
) -> anyhow::Result<Option<FencerStandingItem>> {
  let Some(table) = british_fencing::store::read_table(conn, &entry.table_id).await? else {
    return Ok(None);
  };

  Ok(
    select_british_row(&table, entry.row_index, &entry.licence)
      .map(|row| british_standing_item_for_row(&table, row)),
  )
}

/// Pure lookup: the entry's `row_index` fast path, falling back to a scan by
/// licence on a miss or a mismatch. Split out from [`british_standing_item`]
/// so it is unit-testable without a live Redis connection.
fn select_british_row<'a>(
  table: &'a british_fencing::BritishRankingTable,
  row_index: usize,
  licence: &str,
) -> Option<&'a british_fencing::BritishRankingRow> {
  table
    .rows
    .get(row_index)
    .filter(|row| row.licence == licence)
    .or_else(|| table.rows.iter().find(|row| row.licence == licence))
}

/// Builds a British standing item from one table's row. Pure, so this is
/// unit-testable without a live Redis connection. British has no analogue of
/// `regionId` (British Fencing publishes no regional dimension -- `None`,
/// the same `scope: "regional"`-with-`null`-region shape Division lists
/// already forced clients to handle) or the Unified-only `listCode`/`isNew`/
/// `pointsFloor`/`eligibility` fields.
fn british_standing_item_for_row(
  table: &british_fencing::BritishRankingTable,
  row: &british_fencing::BritishRankingRow,
) -> FencerStandingItem {
  let classifier = build_classifier_info(table.classifier);
  let key = build_standing_key(StandingScope::British, None, &classifier.code);
  let now = Utc::now();
  FencerStandingItem {
    key,
    scope: StandingScope::British,
    region_id: None,
    classifier,
    rank: row.rank.clone(),
    points: Some(row.total_points as f32),
    entrants: Some(table.rows.len()),
    movement: None,
    unified: None,
    british: Some(SourceFreshness {
      source_updated_at: Some(table.source_updated_at.timestamp()),
      fetched_at: Some(table.fetched_at.timestamp()),
      is_stale: Some(now - table.fetched_at > SOURCE_STALE_AFTER),
    }),
  }
}
