#[test]
fn source_freshness_flatten_matches_prior_unified_wire_shape() {
  // Regression for the `SourceFreshness` extraction: `sourceUpdatedAt`/
  // `fetchedAt`/`isStale` used to be flat fields directly on
  // `UnifiedStandingItemMetadata`; they are now `#[serde(flatten)]`ed from a
  // nested `SourceFreshness`, and the wire keys must be byte-for-byte
  // unchanged. `points_floor`/`eligibility` stay `None` here deliberately, so
  // the object contains exactly the five keys this asserts -- no stray key
  // survives an accidental un-skip.
  let metadata = UnifiedStandingItemMetadata {
    freshness: SourceFreshness {
      source_updated_at: Some(1700000000),
      fetched_at: Some(1700000100),
      is_stale: Some(false),
    },
    list_code: Some("CDTWS".to_string()),
    is_new: true,
    points_floor: None,
    eligibility: None,
    counted: Vec::new(),
  };

  let value = serde_json::to_value(&metadata).unwrap();
  assert_eq!(value["sourceUpdatedAt"], 1700000000);
  assert_eq!(value["fetchedAt"], 1700000100);
  assert_eq!(value["isStale"], false);
  assert_eq!(value["listCode"], "CDTWS");
  assert_eq!(value["isNew"], true);
  assert_eq!(value.as_object().unwrap().len(), 5);
}

