/// Resolves `token` to a live share link, for the anonymous share-view read
/// path. Every miss class collapses to `Ok(None)` alike — unknown token,
/// revoked, expired, **or the owner document having since been deleted** —
/// so [`view`]'s handlers render one generic 404 regardless of cause; see
/// the design doc's Revocation section. A `Ok(Err(_))`-shaped distinction
/// here would be exactly the oracle that section rejects.
pub async fn resolve_live_link(token: &str) -> Result<Option<Identified<ResultsShareLinkFields>>> {
  Ok(
    resolve_live_link_with_owner(token)
      .await?
      .map(|resolved| resolved.link),
  )
}

/// A live results share link together with the owner document that established
/// its liveness. Consumers that need owner-scoped data reuse this document
/// rather than issuing another point read.
pub(crate) struct ResolvedResultsShareLink {
  pub(crate) link: Identified<ResultsShareLinkFields>,
  pub(crate) owner: User,
}

/// Resolves `token` to a live results share link and its owner document.
/// Unknown, revoked, expired, and owner-gone links all return `Ok(None)`,
/// preserving the anonymous view's generic-404 contract.
pub(crate) async fn resolve_live_link_with_owner(
  token: &str,
) -> Result<Option<ResolvedResultsShareLink>> {
  Ok(
    resolve_live(
      repository::get_live_by_token(&DB.share_links, token, Utc::now()),
      |fields: &ResultsShareLinkFields| &fields.owner_user_id,
      "failed to query share_links by token",
    )
    .await?
    .map(|(link, owner)| ResolvedResultsShareLink { link, owner }),
  )
}

/// Shared implementation behind [`resolve_live_link`] and
/// [`plan::resolve_live_link`]: awaits `lookup`, folds "owner document since
/// deleted" into the same `Ok(None)` as an unknown/revoked/expired token, and
/// swallows lookup errors before they can leak a token into a log line.
///
/// Deliberately not `?` on `lookup`: `cosmos::Collection::execute_query`
/// folds the query's bound parameters — including the share-link token
/// itself — into this error's `anyhow` context for diagnostics. Propagating
/// `err` (even via `?err` Debug-formatting at a call site) would put the
/// bearer token in a log line. Log a static message and return a fresh,
/// token-free error instead; see the design doc's Logging section ("not even
/// on error").
async fn resolve_live<T: Clone + Eq + ids::HasIdDetail>(
  lookup: impl std::future::Future<Output = Result<Option<Identified<T>>>>,
  owner_user_id: impl FnOnce(&T) -> &TypedId<UserId>,
  lookup_failed_msg: &'static str,
) -> Result<Option<(Identified<T>, User)>> {
  let link = match lookup.await {
    Ok(link) => link,
    Err(_) => {
      tracing::error!("{lookup_failed_msg}");
      return Err(ShareLinkError::Database(anyhow::anyhow!(
        "share-link token lookup failed"
      )));
    }
  };
  let Some(link) = link else {
    return Ok(None);
  };

  let owner = DB
    .users
/// Owner-scoped standings for a live share link: the internal standings
/// assembly entry point (`standings_fencer::get_fencer_standings`), reused
/// exactly as the owner's own `/view/standings/fencer/{fencer_id}` route
/// uses it, but resolving the British Fencing licence from the link's own
/// `owner_user_id` and bound `fencer_id` instead of a Clerk session. No
/// `fencer_id` path segment -- a link can only ever answer for the one
/// fencer it is bound to -- and no `Authorization`/identity header is ever
/// read here, so a signed-in recipient's own session cannot substitute a
/// different fencer or licence (see the module doc's "ignore-recipient-auth"
/// guarantee). Inherits the generic-404, no-store, and rate-limit
/// guarantees the same way every other handler in this module does.
async fn get_share_standings_view(headers: HeaderMap) -> Response {
  if !rate_limit::allow(&headers) {
    return too_many_requests();
  }

  let Some(token) = share_token(&headers) else {
    return unavailable();
  };

  let resolution = match share::resolve_live_link_with_owner(token).await {
    Ok(Some(resolution)) => resolution,
    Ok(None) => return unavailable(),
    Err(err) => {
      error!(error = ?err, "failed to resolve share link for standings view");
      return internal_error();
    }
  };

  render_standings_view(resolution).await
}

async fn render_standings_view(resolution: share::ResolvedResultsShareLink) -> Response {
  let link = resolution.link;
  let rsl_id = TypedId::<ResultsShareLinkId>::database(&link.id);
  let fencer_id = link.fields.fencer_id.clone();

  let british_licence =
    standings_fencer::licence_for_fencer(&resolution.owner.fields.tracked_fencers, &fencer_id)
      .await;

  match standings_fencer::get_fencer_standings(fencer_id, british_licence.as_deref()).await {
    // Same payload as the owner handler: attach movement, then drop
    // unsubstantiated summaries. A Redis miss omits `movement` rather than
    // failing the share page.
    Ok(response) => Json(standings_fencer::standings_view_payload(response).await).into_response(),
    Err(err) => {
      error!(rsl_id = %rsl_id, error = ?err, "failed to load standings for share view");
      internal_error()
    }
  }
}

/// Composition for the exact fencer bound to a live results-share link. The
/// fencer id and British licence are both resolved from the link and owner;
/// neither may be supplied by the recipient.
async fn get_share_standing_composition_view(
  headers: HeaderMap,
  Path(raw_standing_key): Path<String>,
) -> Response {
  if !rate_limit::allow(&headers) {
    return too_many_requests();
  }

  let Some(token) = share_token(&headers) else {
    return unavailable();
  };
  let Ok(standing_key) = standings_fencer::parse_standing_key(&raw_standing_key) else {
    return unavailable();
  };

  let resolution = match share::resolve_live_link_with_owner(token).await {
    Ok(Some(resolution)) => resolution,
    Ok(None) => return unavailable(),
    Err(err) => {
      error!(error = ?err, "failed to resolve share link for standings composition");
      return internal_error();
    }
  };

  render_standing_composition_view(resolution, standing_key).await
}

