/// Owner and anonymous share standings views both go through this so
/// movement attachment cannot drift from composition-verdict filtering.
/// Recommendations still call [`get_fencer_standings`] directly and never
/// see `movement`.
pub(crate) async fn standings_view_payload(
  response: FencerStandingsResponse,
) -> FencerStandingsResponse {
  standings_for_view(history::attach_movement(response).await).await
}

/// `pub(crate)` so the anonymous results-share standings view
/// (`crate::share::view`) can apply the same composition-verdict filtering
/// the owner endpoint applies, rather than serving unsubstantiated summaries
/// through the share surface alone.
pub(crate) async fn standings_for_view(
  response: FencerStandingsResponse,
) -> FencerStandingsResponse {
  let fencer_id = response.fencer_id.clone();
  let identity_resolved = response.identity_resolved;
  let mut evidence = Vec::with_capacity(response.standings.len());
  for item in response.standings {
    let composition = cached_composition_verdict(&fencer_id, &item).await;
    evidence.push((item, composition));
  }

  FencerStandingsResponse {
    fencer_id,
    identity_resolved,
    standings: retain_substantiated(evidence),
  }
}

/// Scope ordering: Unified, then National, then Regional, then British.
/// `sort_standings` sorts scope-major -- every row of a higher-priority
/// scope precedes every row of a lower one, regardless of category;
async fn resolve_standings_usaf_id(fencer_id: &TypedId<FencerId>) -> Result<Option<u32>> {
  if let System::Usaf = fencer_id.system() {
    return Ok(fencer_id.usaf_id());
  }
  if let System::Database = fencer_id.system() {
    match DB.fencers.get_document(fencer_id.as_str()).await {
      Ok(Some(doc)) => {
        return Ok(
          doc
            .fields
            .id_detail
            .usaf_id
            .as_deref()
            .and_then(|id| id.parse().ok()),
        );
      }
  let capture_live = CONF.standings_history.capture_live_compositions;
  let cooldown_active = standings_index::refresh_cooldown_is_active(now)
    .await
    .unwrap_or_else(|error| {
      warn!(
        error = ?error,
        "Failed to read standings refresh cooldown; treating it as inactive"
      );
      false
    });

  let mut state = read_run_state().await.unwrap_or_default();
  state.last_attempt_at = Some(now);
  state.last_attempt_run_id = Some(run_id.clone());
  write_run_state(&state).await?;

  let (connected_fencer_ids, licence_pairs) = get_all_connected_fencer_ids_and_licences()
    .await
    .context("enumerating connected fencers and British Fencing licences")?;
  let mut fencer_ids: Vec<u32> = connected_fencer_ids.into_iter().collect();
  fencer_ids.sort_unstable();

  let licence_by_usaf: HashMap<u32, String> = licence_pairs.into_iter().collect();

  let british_rankings_enabled = british_rankings_enabled().await.unwrap_or_else(|error| {
    warn!(
      error = ?error,
      "Failed to read British rankings runtime flag; treating standings history capture as British-disabled this run"
    );
    false
  });
  if !british_rankings_enabled {
    warn!(
      run_id = %run_id,
      "British rankings runtime flag (standings.british_rankings_enabled) is disabled; \
       this capture run will write no British (gb-) snapshots -- every tracked fencer with a \
       British licence will read as unranked rather than uncaptured until it is re-enabled"
    );
  }
  table
    .rows
    .get(row_index)
    .filter(|row| row.licence == licence)
    .or_else(|| table.rows.iter().find(|row| row.licence == licence))
}
